 function mount(){if(e.swimming){announce(ft('farShore'));return;}if(!f.mounted&&v.vehicle==='car'){if(e.carHealth<=0){announce(ft('wrecked'));return;}if(e.parked&&distance(f,e.parked)>3){announce(ft('findCar'));return;}}if(f.mounted&&v.vehicle==='car')parkCar(state,motion.heading);if(world.interior){announce(ft('exitHome'));return;}const entry=!f.mounted&&v.vehicle==='car'&&e.parked?e.parked:f;if(!f.mounted&&!canStand(world,entry.x,entry.y,VEHICLES[v.vehicle].radius)){announce(ft('roadBlocked'));return;}if(!toggleMount(state)){announce(ft('mountBlocked'));return;}if(f.mounted&&v.vehicle==='car'){if(e.parked){f.x=e.parked.x;f.y=e.parked.y;f.angle=e.parked.angle;}e.parked=null;}motion.speed=0;motion.heading=f.angle;aiming=false;cancelRoute();audio.tone('click');updateHUD();persist();canvas.focus({preventScroll:true});}
